package com.gathin.tvhome;
import org.junit.Test;
import java.util.*;
import static org.junit.Assert.*;
public class SetupProposalTest {
    private Map<String,Object> draft(Map<String,Object> settings){Map<String,Object> d=new LinkedHashMap<>();d.put("schema",1);d.put("settings",settings);return d;}
    @Test public void mapsHumanChoicesToOnlyLauncherPreferences(){SetupProposal p=new SetupProposal(draft(new HashMap<String,Object>(){{put("experience","glass");put("position","bottom");put("columns",8);put("text","dark");put("textSize",110);put("names","selected");put("strongFocus",true);put("idleSeconds",60);}}),Collections.emptySet());assertEquals("glass",p.values.get(ExperiencePolicy.KEY));assertEquals(2,p.values.get(HomePolish.INK));assertEquals("v1,110,110,110",p.values.get(HomeAppearance.KEY));assertEquals(2,p.values.get(HomePolish.NAMES));}
    @Test public void noCommandsOrPermissionExpansionCanEnterTheContract(){for(String key:Arrays.asList("shell","adb","permissions","settings_secure","url","apiKey")){Map<String,Object>d=draft(Collections.singletonMap(key,true));try{new SetupProposal(d,Collections.emptySet());fail(key);}catch(IllegalArgumentException expected){}}}
    @Test public void favoritesMustBeAvailableUniquePackages(){Map<String,Object>d=draft(Collections.singletonMap("columns",8));d.put("favorites",Arrays.asList("org.example.a","org.example.a"));try{new SetupProposal(d,new HashSet<>(Arrays.asList("org.example.a")));fail();}catch(IllegalArgumentException expected){}d.put("favorites",Arrays.asList("org.example.missing"));try{new SetupProposal(d,Collections.emptySet());fail();}catch(IllegalArgumentException expected){}}
    @Test public void rejectsCoercionAndUnknownEnumerations(){for(Object value:Arrays.asList("8",8.0,1,9)){try{new SetupProposal(draft(Collections.singletonMap("columns",value)),Collections.emptySet());fail();}catch(IllegalArgumentException expected){}}for(String v:Arrays.asList("tvOS","https://theme","")){try{new SetupProposal(draft(Collections.singletonMap("experience",v)),Collections.emptySet());fail();}catch(IllegalArgumentException expected){}}}
    @Test public void appOrderSurvivesAndUnspecifiedChoicesAreAbsent(){Map<String,Object>d=draft(Collections.singletonMap("position","top"));d.put("favorites",Arrays.asList("org.example.b","org.example.a"));SetupProposal p=new SetupProposal(d,new HashSet<>(Arrays.asList("org.example.a","org.example.b")));assertEquals(Arrays.asList("org.example.b","org.example.a"),p.favorites);assertEquals(1,p.values.size());}
    @org.junit.Test public void newTvDefaultsExcludeMissingAppsWithoutLosingVisibleOrder(){java.util.List<String> original=java.util.Arrays.asList("org.missing.app","org.good.b","org.good.a","org.good.b");java.util.Set<String> available=new java.util.HashSet<>(java.util.Arrays.asList("org.good.a","org.good.b"));org.junit.Assert.assertEquals(java.util.Arrays.asList("org.good.b","org.good.a"),SetupProposal.visibleDefaults(original,available));org.junit.Assert.assertEquals(4,original.size());}
}
